/** Remove the rows generated by the retired admin demo seeder. */
import { connectDatabase, disconnectDatabase } from '../src/config/database.js';
import { createChildLogger } from '../src/config/logger.js';
import { AdminCouponModel } from '../src/modules/admin/models/coupon.model.js';
import { AdminCustomerModel } from '../src/modules/admin/models/customer.model.js';
import { AdminOrderModel } from '../src/modules/admin/models/order.model.js';
import { AdminRestockModel } from '../src/modules/admin/models/restock.model.js';
import { AdminReviewModel } from '../src/modules/admin/models/review.model.js';
import { AdminReturnModel } from '../src/modules/admin/models/return.model.js';
import { CartInterestModel } from '../src/modules/cart/cart.model.js';
import { ProductModel } from '../src/modules/products/products.model.js';
import { recalculateProductRating } from '../src/modules/reviews/reviews.service.js';
import { WishlistEntryModel } from '../src/modules/wishlist/wishlist.model.js';

const log = createChildLogger('demo-data-cleanup');

async function main(): Promise<void> {
  await connectDatabase();

  // The retired generator used synthetic `CUS-####` ids and the literal
  // `guest`; actual checkouts use the signed-in User ObjectId as customerId.
  const demoOrders = await AdminOrderModel.find({ customerId: /^(CUS-\d+|guest)$/ })
    .select('orderId')
    .lean();
  const demoOrderIds = demoOrders.map((order) => order.orderId);
  const realProductSlugs = await ProductModel.distinct('slug');

  const [orders, customers, returns, reviews, coupons, restocks, wishlist, cartInterest] =
    await Promise.all([
      AdminOrderModel.deleteMany({ customerId: /^(CUS-\d+|guest)$/ }),
      AdminCustomerModel.deleteMany({ customerId: /^CUS-\d+$/ }),
      demoOrderIds.length > 0
        ? AdminReturnModel.deleteMany({ orderId: { $in: demoOrderIds } })
        : Promise.resolve({ deletedCount: 0 }),
      // Real storefront submissions always carry the authenticated user id.
      AdminReviewModel.deleteMany({ $or: [{ userId: { $exists: false } }, { userId: '' }] }),
      // These three codes were only generated by the demo history seeder;
      // active storefront coupons PAPER10, SAVE5 and PREPAID100 are preserved.
      AdminCouponModel.deleteMany({ code: { $in: ['BULK9', 'FESTIVE15', 'WELCOME200'] } }),
      // No real restock event writer exists in the application yet.
      AdminRestockModel.deleteMany({}),
      realProductSlugs.length > 0
        ? WishlistEntryModel.deleteMany({ productId: { $nin: realProductSlugs } })
        : Promise.resolve({ deletedCount: 0 }),
      realProductSlugs.length > 0
        ? CartInterestModel.deleteMany({ productId: { $nin: realProductSlugs } })
        : Promise.resolve({ deletedCount: 0 }),
    ]);

  // Seeded history wrote aggregate counters onto coupons and products. Rebuild
  // both from the real order/review rows left after cleanup.
  const [couponTotals, couponRows, products] = await Promise.all([
    AdminOrderModel.aggregate<{ _id: string; used: number; discountGiven: number }>([
      { $match: { couponCode: { $exists: true, $ne: '' } } },
      { $group: { _id: '$couponCode', used: { $sum: 1 }, discountGiven: { $sum: '$discount' } } },
    ]),
    AdminCouponModel.find().select('code').lean(),
    ProductModel.find().select('slug').lean(),
  ]);
  const totalsByCode = new Map(couponTotals.map((entry) => [entry._id, entry]));
  if (couponRows.length > 0) {
    await AdminCouponModel.bulkWrite(couponRows.map((coupon) => {
      const totals = totalsByCode.get(coupon.code);
      return {
        updateOne: {
          filter: { code: coupon.code },
          update: { $set: { used: totals?.used ?? 0, discountGiven: totals?.discountGiven ?? 0 } },
        },
      };
    }));
  }
  for (const product of products) await recalculateProductRating(product.slug);

  log.info(
    {
      orders: orders.deletedCount,
      customers: customers.deletedCount,
      returns: returns.deletedCount,
      reviews: reviews.deletedCount,
      coupons: coupons.deletedCount,
      restocks: restocks.deletedCount,
      staleWishlist: wishlist.deletedCount,
      staleCartInterest: cartInterest.deletedCount,
      couponsRecalculated: couponRows.length,
      productRatingsRecalculated: products.length,
    },
    'Removed demo rows; customer accounts and catalogue products were preserved',
  );

  await disconnectDatabase();
}

main().catch(async (error: unknown) => {
  log.error({ message: error instanceof Error ? error.message : String(error) }, 'Demo data cleanup failed');
  await disconnectDatabase().catch(() => undefined);
  process.exitCode = 1;
});
